parameters.text:
=Supply Chain workflow stopped
Run: {{ $json.runId }}
Time: {{ $json.failedAt }}
Reason: {{ $json.failureReason }}

=Analyze this supply-chain risk run and return ONLY valid JSON (no markdown fences).

Run: {{ $json.runId }}
maxSeverity: {{ $json.maxSeverity }}
varTotal: {{ $json.varTotal }}
spofCount: {{ $json.spofCount }}

SPOFs:
{{ JSON.stringify(($json.spofs || []).slice(0, 12)) }}

Graph nodes:
{{ JSON.stringify(($json.graph.nodes || []).slice(0, 30)) }}

Edges:
{{ JSON.stringify(($json.graph.edges || []).slice(0, 40)) }}

Required JSON keys only:
- executiveSummary (string)
- topSpofs (array of {id,label,reason,varProxy,riskLevel})
- mitigations (string array, 3-5 items)

Do NOT return mermaid or diagram markup. Visualization is generated separately as GraphViz DOT.

parameters.jsCode:
// Parse AI Agent JSON + build GraphViz DOT (Kroki-reliable; no Mermaid)
const raw = $input.first().json;
const scored = $('SPOF VaR Scoring').first().json;

let content = raw?.output ?? raw?.text ?? raw?.choices?.[0]?.message?.content ?? raw?.content ?? '';
if (typeof content !== 'string') content = JSON.stringify(content);

let parsed = null;
try {
  const cleaned = content.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = null;
}

function buildGraphVizDot(graph, spofs) {
  const spofIds = new Set((spofs || []).map((s) => s.id));
  const lines = [
    'digraph G {',
    '  rankdir=LR;',
    '  bgcolor="white";',
    '  node [shape=box, style="rounded,filled", fontname="Helvetica", fontsize=10];',
    '  edge [fontname="Helvetica", fontsize=9];',
  ];

  const shapes = {
    supplier: 'box',
    material: 'ellipse',
    plant: 'folder',
    lane: 'hexagon',
  };

  for (const n of (graph.nodes || []).slice(0, 40)) {
    const id = String(n.id).replace(/[^a-zA-Z0-9]/g, '_');
    const label = String(n.label || n.id)
      .replace(/\\/g, ' ')
      .replace(/"/g, "'")
      .replace(/[^a-zA-Z0-9 ._-]/g, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 36);
    const isSpof = spofIds.has(n.id) || n.isSpof;
    const shape = shapes[n.type] || 'box';
    const fill = isSpof ? '#ffcccc' : (
      n.type === 'supplier' ? '#e8f4ff' :
      n.type === 'material' ? '#eaffea' :
      n.type === 'plant' ? '#fff4e0' : '#f0e8ff'
    );
    lines.push(`  ${id} [label="${label}", shape=${shape}, fillcolor="${fill}"];`);
  }

  for (const e of (graph.edges || []).slice(0, 60)) {
    const a = String(e.from).replace(/[^a-zA-Z0-9]/g, '_');
    const b = String(e.to).replace(/[^a-zA-Z0-9]/g, '_');
    lines.push(`  ${a} -> ${b};`);
  }

  lines.push('}');
  return lines.join('\n');
}

const executiveSummary = parsed?.executiveSummary || parsed?.summary ||
  `Supply chain risk run ${scored.runId}: ${scored.spofCount} SPOFs, VaR ~$${scored.varTotal}, max severity ${scored.maxSeverity}.`;

const topSpofs = Array.isArray(parsed?.topSpofs) ? parsed.topSpofs : (scored.spofs || []).slice(0, 5).map((s) => ({
  id: s.id,
  label: s.label,
  reason: s.type,
  varProxy: s.varProxy,
  riskLevel: s.riskLevel,
}));

const mitigations = Array.isArray(parsed?.mitigations) && parsed.mitigations.length
  ? parsed.mitigations
  : [
      'Qualify alternate suppliers for sole-source materials',
      'Add secondary logistics lanes for high-disruption routes',
      'Increase safety stock on critical materials',
      'Negotiate dual-source contracts for top VaR nodes',
    ];

const diagramSource = buildGraphVizDot(scored.graph, scored.spofs);

return [{
  json: {
    ...scored,
    ai: {
      executiveSummary,
      topSpofs,
      mitigations,
      parseOk: Boolean(parsed),
      model: scored.groqModel,
      rawOutput: typeof content === 'string' ? content.slice(0, 2000) : '',
    },
    diagramSource,
    executiveSummary,
    mitigations,
    topSpofs,
  },
}];

// Local SVG graph — always read scored graph from SPOF node (authoritative)
function asArray(v) {
  if (Array.isArray(v)) return v;
  if (v && typeof v === 'object') return Object.values(v);
  return [];
}

const input = $input.first().json;

// Prefer live scored payload; fall back to upstream refs
let scored;
try { scored = $('SPOF VaR Scoring').first().json; } catch (e) { scored = null; }
try {
  if (!scored?.graph?.nodes) scored = $('Code Parse Groq Payload').first().json;
} catch (e) { /* ignore */ }

const graph = scored?.graph || input.graph || { nodes: [], edges: [] };
const spofs = asArray(scored?.spofs || input.spofs);
const spofIds = new Set(spofs.map((s) => s && s.id).filter(Boolean));
const runId = scored?.runId || input.runId || 'run';

const nodes = asArray(graph.nodes)
  .filter((n) => n && (n.id || n.label || n.type))
  .slice(0, 40)
  .map((n) => {
    const id = String(n.id || `${n.type || 'node'}_${Math.random().toString(36).slice(2, 7)}`);
    let label = n.label || n.name || n.id || '';
    label = String(label)
      .replace(/undefined/gi, '')
      .replace(/→/g, '->')
      .replace(/\s+/g, ' ')
      .trim();
    if (!label || /undefined/i.test(label)) {
      if (n.name) label = String(n.name);
      else if (id.includes(':') && !id.includes('undefined')) label = id.split(':').slice(1).join(':');
      else if (n.supplier_id) label = String(n.supplier_id);
      else if (n.material_id) label = String(n.material_id);
      else if (n.plant_id) label = String(n.plant_id);
      else if (n.lane_id) label = String(n.lane_id);
      else if (n.origin || n.destination) label = `${n.origin || '?'}->${n.destination || '?'}`;
      else label = id.replace(/undefined/g, '?');
    }
    return { ...n, id, label: label.slice(0, 32), type: n.type || 'material' };
  })
  .filter((n) => !String(n.id).includes('undefined') && n.label && n.label !== '?');

const nodeIdSet = new Set(nodes.map((n) => n.id));
const edges = asArray(graph.edges)
  .filter((e) => e && nodeIdSet.has(e.from) && nodeIdSet.has(e.to))
  .slice(0, 60);

const layers = {
  supplier: nodes.filter((n) => n.type === 'supplier'),
  material: nodes.filter((n) => n.type === 'material'),
  plant: nodes.filter((n) => n.type === 'plant'),
  lane: nodes.filter((n) => n.type === 'lane'),
};

// If typing missing, dump all in one column rather than empty chart
const anyLayer = Object.values(layers).some((l) => l.length);
if (!anyLayer && nodes.length) {
  layers.material = nodes;
}

const colX = { supplier: 40, material: 280, plant: 520, lane: 760 };
const boxW = 200;
const boxH = 36;
const gapY = 12;
const startY = 70;
const pos = {};

for (const [type, list] of Object.entries(layers)) {
  list.forEach((n, i) => {
    pos[n.id] = { x: colX[type] ?? 280, y: startY + i * (boxH + gapY), w: boxW, h: boxH };
  });
}

const maxY = Math.max(220, ...Object.values(pos).map((p) => p.y + p.h + 40), 220);
const width = 1020;
const height = maxY;

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function fillFor(n) {
  if (spofIds.has(n.id) || n.isSpof) return '#ffcccc';
  if (n.type === 'supplier') return '#e8f4ff';
  if (n.type === 'material') return '#eaffea';
  if (n.type === 'plant') return '#fff4e0';
  return '#f0e8ff';
}

const parts = [];
parts.push(`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">`);
parts.push('<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 Z" fill="#888"/></marker></defs>');
parts.push('<rect width="100%" height="100%" fill="#ffffff"/>');
parts.push(`<text x="40" y="28" font-family="Arial, Helvetica, sans-serif" font-size="16" font-weight="bold" fill="#111">Supply Chain Risk Map — ${esc(runId)}</text>`);
parts.push(`<text x="40" y="48" font-family="Arial, Helvetica, sans-serif" font-size="11" fill="#666">Nodes: ${nodes.length} | Edges: ${edges.length} | SPOFs: ${spofIds.size} | Red=SPOF</text>`);

if (!nodes.length) {
  parts.push('<text x="40" y="100" font-family="Arial" font-size="14" fill="#cc0000">No graph nodes found. Check SPOF VaR Scoring output.</text>');
} else {
  for (const e of edges) {
    const a = pos[e.from];
    const b = pos[e.to];
    if (!a || !b) continue;
    parts.push(`<line x1="${a.x + a.w}" y1="${a.y + a.h / 2}" x2="${b.x}" y2="${b.y + b.h / 2}" stroke="#888" stroke-width="1.5" marker-end="url(#arrow)"/>`);
  }
  for (const n of nodes) {
    const p = pos[n.id];
    if (!p) continue;
    const stroke = (spofIds.has(n.id) || n.isSpof) ? '#cc0000' : '#333';
    parts.push(`<rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" rx="6" fill="${fillFor(n)}" stroke="${stroke}" stroke-width="1.5"/>`);
    parts.push(`<text x="${p.x + 8}" y="${p.y + 23}" font-family="Arial, Helvetica, sans-serif" font-size="11" fill="#111">${esc(n.label)}</text>`);
  }
}

parts.push('</svg>');
const svg = parts.join('');

return [{
  json: {
    ...input,
    runId,
    graphNodeCount: nodes.length,
    graphEdgeCount: edges.length,
    graphRenderedLocally: true,
    graphFormat: 'svg',
  },
  binary: {
    data: {
      data: Buffer.from(svg, 'utf8').toString('base64'),
      mimeType: 'image/svg+xml',
      fileName: `supply-chain-risk-${runId}.svg`,
      fileExtension: 'svg',
    },
  },
}];

parameters.text:
=Supply Chain Risk Alert
Run: {{ $('Set Visualization Payload').item.json.runId }}
Severity: {{ $('Set Visualization Payload').item.json.maxSeverity }}
SPOFs: {{ $('Set Visualization Payload').item.json.spofCount }} | VaR: ${{ $('Set Visualization Payload').item.json.varTotal }}
{{ $('Set Visualization Payload').item.json.executiveSummary }}
Notion: {{ $json.url || ('https://notion.so/' + ($json.id || '').replaceAll('-', '')) }}
Graph: {{ $('Set Dashboard Fields').item.json.graphImageUrl }}

parameters.jsCode:
// Normalize & Join — reject Sheets auth/error rows before building graph
function rowsFrom(nodeName) {
  const items = $(nodeName).all().map((i) => i.json);
  const errors = items.filter((r) => r && (r.error || r.message === 'Unauthorized' || r.name === 'Error'));
  if (errors.length && items.length === errors.length) {
    const msg = String(errors[0].error || errors[0].message || 'Google Sheets read failed');
    throw new Error(nodeName + ' failed: ' + msg + ' — Reconnect Google Sheets OAuth credential and re-run.');
  }
  // Keep only real data rows (must have an id-like field)
  return items.filter((r) => r && !r.error && (
    r.supplier_id || r.material_id || r.lane_id || r.plant_id
  ));
}

const suppliers = rowsFrom('Read Suppliers');
const materials = rowsFrom('Read Materials');
const logistics = rowsFrom('Read Logistics Lanes');
const plants = rowsFrom('Read Plants Sites');
const config = $('Set Workflow Config').first().json;

if (!suppliers.length || !materials.length) {
  throw new Error('No valid supplier/material rows after Sheets read. Check OAuth + sheet tabs/columns.');
}

const nodes = [];
const edges = [];
const seen = new Set();

function addNode(id, type, label, extra = {}) {
  const key = String(id);
  if (!key || key.includes('undefined') || key.endsWith(':')) return;
  if (seen.has(key)) return;
  seen.add(key);
  nodes.push({ id: key, type, label: label || key, ...extra });
}

for (const s of suppliers) {
  addNode(`sup:${s.supplier_id}`, 'supplier', s.name || s.supplier_id, {
    country: s.country,
    tier: s.tier,
    criticality: s.criticality,
    annual_spend: Number(s.annual_spend) || 0,
  });
}
for (const p of plants) {
  addNode(`plant:${p.plant_id}`, 'plant', p.name || p.plant_id, {
    region: p.region,
    capacity_units: Number(p.capacity_units) || 0,
    has_alternate_source:
      String(p.has_alternate_source).toLowerCase() === 'true' ||
      p.has_alternate_source === true ||
      p.has_alternate_source === 1,
  });
}
for (const m of materials) {
  const mid = `mat:${m.material_id}`;
  addNode(mid, 'material', m.name || m.material_id, {
    lead_time_days: Number(m.lead_time_days) || 0,
    unit_cost: Number(m.unit_cost) || 0,
    annual_volume: Number(m.annual_volume) || 0,
    sole_source:
      String(m.sole_source).toLowerCase() === 'true' ||
      m.sole_source === true ||
      m.sole_source === 1,
    supplier_id: m.supplier_id,
    plant_id: m.plant_id,
  });
  if (m.supplier_id) edges.push({ from: `sup:${m.supplier_id}`, to: mid, kind: 'supplies' });
  if (m.plant_id) edges.push({ from: mid, to: `plant:${m.plant_id}`, kind: 'consumed_at' });
}
for (const l of logistics) {
  const lid = `lane:${l.lane_id}`;
  addNode(lid, 'lane', `${l.origin}->${l.destination}`, {
    mode: l.mode,
    transit_days: Number(l.transit_days) || 0,
    disruption_risk: Number(l.disruption_risk) || 0,
    origin: l.origin,
    destination: l.destination,
  });
  const destPlant = plants.find(
    (p) =>
      String(p.name).toLowerCase() === String(l.destination).toLowerCase() ||
      String(p.plant_id) === String(l.destination),
  );
  if (destPlant) edges.push({ from: lid, to: `plant:${destPlant.plant_id}`, kind: 'serves' });
}

return [{
  json: {
    ...config,
    suppliers,
    materials,
    logistics,
    plants,
    graph: { nodes, edges },
    counts: {
      suppliers: suppliers.length,
      materials: materials.length,
      logistics: logistics.length,
      plants: plants.length,
      nodes: nodes.length,
      edges: edges.length,
    },
  },
}];

// SPOF + VaR Scoring
const item = $input.first().json;
const { graph, materials, logistics, plants, varThreshold, spofCountThreshold } = item;
const nodes = graph.nodes.map((n) => ({ ...n }));
const edges = graph.edges;

// Count suppliers per material_id at plant
const materialKeys = {};
for (const m of materials) {
  const key = `${m.material_id}@@${m.plant_id}`;
  if (!materialKeys[key]) materialKeys[key] = [];
  materialKeys[key].push(m);
}

const spofs = [];
let varTotal = 0;

for (const m of materials) {
  const key = `${m.material_id}@@${m.plant_id}`;
  const peers = materialKeys[key] || [];
  const sole = peers.length <= 1 || String(m.sole_source).toLowerCase() === 'true' || m.sole_source === true || m.sole_source === 1;
  const unitCost = Number(m.unit_cost) || 0;
  const volume = Number(m.annual_volume) || 0;
  const disruption = sole ? 1 : 0.35;
  const varProxy = unitCost * volume * disruption;
  const nodeId = `mat:${m.material_id}`;
  const node = nodes.find((n) => n.id === nodeId);
  if (node) {
    node.varProxy = varProxy;
    node.isSpof = sole;
    node.riskLevel = sole && varProxy >= (varThreshold || 50000) ? 'critical' : sole ? 'high' : varProxy >= (varThreshold || 50000) ? 'medium' : 'low';
  }
  if (sole) {
    spofs.push({
      id: nodeId,
      type: 'material_sole_source',
      label: m.name || m.material_id,
      supplier_id: m.supplier_id,
      plant_id: m.plant_id,
      varProxy,
      riskLevel: node ? node.riskLevel : 'high',
    });
    varTotal += varProxy;
  } else {
    varTotal += varProxy * 0.25;
  }
}

// Lane SPOFs: high disruption and no alternate lane to same destination
const byDest = {};
for (const l of logistics) {
  const d = String(l.destination);
  if (!byDest[d]) byDest[d] = [];
  byDest[d].push(l);
}
for (const l of logistics) {
  const risk = Number(l.disruption_risk) || 0;
  const alts = (byDest[String(l.destination)] || []).filter((x) => x.lane_id !== l.lane_id);
  const isSpofLane = risk >= 0.6 && alts.length === 0;
  const nodeId = `lane:${l.lane_id}`;
  const node = nodes.find((n) => n.id === nodeId);
  const laneVar = risk * 25000;
  if (node) {
    node.varProxy = laneVar;
    node.isSpof = isSpofLane;
    node.riskLevel = isSpofLane ? (risk >= 0.8 ? 'critical' : 'high') : risk >= 0.5 ? 'medium' : 'low';
  }
  if (isSpofLane) {
    spofs.push({
      id: nodeId,
      type: 'logistics_lane',
      label: `${l.origin}→${l.destination}`,
      disruption_risk: risk,
      varProxy: laneVar,
      riskLevel: node ? node.riskLevel : 'high',
    });
    varTotal += laneVar;
  }
}

const severityRank = { critical: 4, high: 3, medium: 2, low: 1 };
let maxSeverity = 'low';
for (const s of spofs) {
  if ((severityRank[s.riskLevel] || 0) > (severityRank[maxSeverity] || 0)) maxSeverity = s.riskLevel;
}
if (spofs.length === 0) maxSeverity = 'low';

const alertNeeded =
  ['critical', 'high'].includes(maxSeverity) ||
  varTotal >= (varThreshold || 50000) ||
  spofs.length >= (spofCountThreshold || 2);

return [{
  json: {
    ...item,
    graph: { nodes, edges },
    spofs,
    varTotal: Math.round(varTotal),
    maxSeverity,
    alertNeeded,
    spofCount: spofs.length,
    scoringSummary: {
      spofCount: spofs.length,
      varTotal: Math.round(varTotal),
      maxSeverity,
      alertNeeded,
    },
  },
}];
